package com.franco.desco.adapter.in.web.property;

import com.franco.desco.application.property.PropertyCommands;import com.franco.desco.application.shared.pagination.PageRequest;import com.franco.desco.domain.property.PropertyModels;import org.springframework.stereotype.Component;
@Component public class PropertyWebMapper{
 public PropertyCommands.ListProperties list(int p,int s,String buscar,Long socioId,String distritoCodigo,Boolean soloActivos){return new PropertyCommands.ListProperties(new PageRequest<>(p,s,new PropertyCommands.Filter(buscar,socioId,distritoCodigo,soloActivos),null,null));}
 public PropertyCommands.CreateProperty command(PropertyRequests.Create r){return new PropertyCommands.CreateProperty(null,r.nombre(),r.fechaRegistro(),loc(r.ubicacion()),chars(r.caracteristicas()),r.titulares().stream().map(this::owner).toList());}
 public PropertyCommands.UpdateProperty command(Long id,PropertyRequests.Update r){return new PropertyCommands.UpdateProperty(id,null,r.nombre(),r.fechaTitularidad(),r.ubicacion()==null?null:loc(r.ubicacion()),r.caracteristicas()==null?null:chars(r.caracteristicas()),r.titulares()==null?null:r.titulares().stream().map(this::owner).toList());}
 private PropertyCommands.Location loc(PropertyRequests.Location x){return new PropertyCommands.Location(x.distritoCodigo(),x.centroPobladoId(),x.referencia(),x.latitud(),x.longitud(),x.altitudM());} private PropertyCommands.Characteristics chars(PropertyRequests.Characteristics x){return new PropertyCommands.Characteristics(x.areaTotalHa(),x.areaCultivableHa(),x.tipoRiego(),x.fuenteAgua(),x.infraestructura(),x.observacion(),x.fechaDesde());} private PropertyCommands.Owner owner(PropertyRequests.Owner x){return new PropertyCommands.Owner(x.socioId(),x.tipoTitularidad(),x.porcentaje());}
 public PropertyResponses.Summary response(PropertyModels.Summary v){return new PropertyResponses.Summary(v.predioId(),v.codigo(),v.nombre(),v.fechaRegistro(),v.estado(),v.distritoCodigo(),v.centroPobladoId(),v.referencia(),v.areaTotalHa(),v.areaCultivableHa(),v.tipoRiego(),v.titulares());}
 public PropertyResponses.Detail response(PropertyModels.Detail v){return new PropertyResponses.Detail(v.predioId(),v.codigo(),v.nombre(),v.fechaRegistro(),v.estado(),v.ubicacionId(),v.distritoCodigo(),v.centroPobladoId(),v.referencia(),v.latitud(),v.longitud(),v.altitudM(),v.predioVersionId(),v.areaTotalHa(),v.areaCultivableHa(),v.tipoRiego(),v.fuenteAgua(),v.infraestructura(),v.observacion(),v.fechaDesde(),v.titulares().stream().map(x->new PropertyResponses.Owner(x.predioTitularidadId(),x.socioId(),x.tipoDocumento(),x.numeroDocumento(),x.nombres(),x.apellidoPaterno(),x.apellidoMaterno(),x.tipoTitularidad(),x.porcentaje(),x.fechaDesde(),x.fechaHasta(),x.estado())).toList(),v.versiones().stream().map(x->new PropertyResponses.Version(x.predioVersionId(),x.areaTotalHa(),x.areaCultivableHa(),x.tipoRiego(),x.fuenteAgua(),x.infraestructura(),x.observacion(),x.fechaDesde(),x.fechaHasta(),x.estado())).toList(),v.parcelas().stream().map(x->new PropertyResponses.Plot(x.parcelaId(),x.parcelaCodigo(),x.parcelaNombre(),x.areaHa(),x.parcelaEstado(),x.ubicacionId(),x.parcelaCultivoId(),x.variedadPaltaId(),x.variedad(),x.fechaInicio(),x.fechaFin(),x.situacionCultivo(),x.cultivoEstado())).toList(),v.archivos().stream().map(x->new PropertyResponses.FileRef(x.archivoId(),x.nombreOriginal(),x.mimeType(),x.secureUrl(),x.fechaCarga(),x.categoria(),x.origenCaptura())).toList());}
}
